layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU, vL;
    void main(){
      float u = uTime - aT - 0.04; if (u < 0. || u > 0.36){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = aE - aO; float L = length(d); vec3 f = d/L;
      float x = (position.x*.5 + .5)*(L + .2) - .1;                       // metres along the dash
      vec3 P = aO + f*x;
      vec3 cside = normalize(cross(f, P - cameraPosition));
      vec3 side = normalize(vec3(0., 1., 0.) + .25*cside*sign(dot(cside, vec3(0., 1., 0.)) + 1e-4));   // stays upright
      float y = (position.y*.5 + .5)*1.8;                                   // metres above the ground
      vP = vec2(x, y); vU = u; vL = L;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*(y - .9) + vec3(0., .9, 0.), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vL;
    float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h2(i), h2(i + vec2(1,0)), f.x), mix(h2(i + vec2(0,1)), h2(i + vec2(1,1)), f.x), f.y); }
    float fbm(vec2 p){ float s = 0., a = .55; for (int i = 0; i < 4; i++){ s += a*vn(p); p = p*2.03 + 7.1; a *= .5; } return s; }
    void main(){
      float x = vP.x, y = vP.y, u = vU;
      float head = vL*(1. - pow(1. - clamp(u/0.16, 0., 1.), 3.)) - .1;   // just behind the Scout (same ease)
      float q = x/max(head, .01);                                              // 0 at the origin, 1 at the Scout
      float wipe = max(u - 0.06, 0.)/.17;                   // eaten from the origin
      // cloud: fbm stretched along the dash (never grain), drifting back, breaking up as it thins
      vec2 np = vec2(x*1.3 - u*4.5, y*5.5);
      float n = fbm(np), n2 = fbm(np*vec2(.6, 1.7) + 3.3);
      float env = pow(clamp(q, 0., 1.), 1.2)*smoothstep(1.04, .8, q)*step(0., q);   // thin at the origin, full at the Scout, melts into the body
      float hgt = .55 + .35*env;                                               // half-height grows toward the Scout (body-tall)
      float yc = abs(y - 1.) / hgt;
      float body = smoothstep(1., .25, yc + (n2 - .5)*.5);                     // soft ragged top/bottom
      float alive = smoothstep(wipe - .1, wipe + .3, q + (n - .5)*.35);        // wiped from the origin, ragged front
      float dens = smoothstep(.32, .85, n*(.55 + .6*body))*body*env*alive;
      float fade = 1. - smoothstep(0.26, 0.36, u);
      dens *= fade;
      vec3 col = mix(uOrange*.55, mix(uOrange, uGold, .6), smoothstep(.2, .8, dens));   // dim warm edges → gold where dense
      vec3 o = col*dens*.55 + vec3(1., .93, .8)*pow(dens, 3.)*.25;
      o *= smoothstep(-.05, .15, x);
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
